import { createHmac } from 'node:crypto'

export interface ConnectorConfig {
  /** Zendesk webhook secret for HMAC-SHA256 verification of X-Zendesk-Webhook-Signature header */
  zendeskWebhookSecret: string
  /** Pusher Channels App ID */
  pusherAppId: string
  /** Pusher Channels App Key (sent as X-Pusher-Key header) */
  pusherAppKey: string
  /** Pusher Channels App Secret (used for HMAC-SHA256 signature) */
  pusherAppSecret: string
  /** Pusher cluster identifier (e.g., 'mt1', 'eu', 'ap1') */
  pusherCluster: string
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
}

export interface ZendeskWebhookPayload {
  account_id: number
  id: string
  type: string
  subject: string
  time: string
  zendesk_event_version: string
  event: {
    type: string
    source: string
  }
  detail: {
    id: number
    subject: string
    priority: string
    status: string
    assignee_id: number | null
    updated_at: string
    current: {
      status: string
      assignee_id: number | null
      priority: string
    }
    previous: {
      status: string
      assignee_id: number | null
      priority: string
    }
  }
}

export interface HandleResult {
  pusherChannel: string
  pusherEvent: string
  ticketId: number
  status: string
}

function validatePayload(payload: unknown): asserts payload is ZendeskWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Invalid payload: expected object')
  }
  const p = payload as Record<string, unknown>
  if (!p.detail || typeof p.detail !== 'object') {
    throw new Error('Missing required field: detail')
  }
  const detail = p.detail as Record<string, unknown>
  if (typeof detail.id !== 'number') {
    throw new Error('Missing required field: detail.id (ticket ID)')
  }
  if (typeof detail.status !== 'string') {
    throw new Error('Missing required field: detail.status')
  }
  if (typeof detail.updated_at !== 'string') {
    throw new Error('Missing required field: detail.updated_at')
  }
}

function verifyZendeskSignature(
  payload: string,
  signatureHeader: string | null,
  secret: string
): void {
  if (!signatureHeader) {
    throw new Error('Missing X-Zendesk-Webhook-Signature header')
  }
  const expected = createHmac('sha256', secret).update(payload).digest('hex')
  // Zendesk sends signature as hex string
  if (signatureHeader !== expected) {
    throw new Error('Invalid Zendesk webhook signature')
  }
}

function generatePusherSignature(
  body: string,
  secret: string
): string {
  return createHmac('sha256', secret).update(body).digest('hex')
}

export async function handle(
  payload: ZendeskWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  // Validate required fields
  validatePayload(payload)

  const { detail } = payload
  const ticketId = detail.id
  const status = detail.status
  const assigneeId = detail.assignee_id
  const updatedAt = detail.updated_at

  // Format channel name as presence channel per Pusher convention
  const channelName = `presence-ticket-${ticketId}`
  const eventName = 'ticket.updated'

  // Build event data - include assignee_id since name lookup requires separate API call
  const eventData: Record<string, unknown> = {
    status,
    updated_at: updatedAt,
  }
  if (assigneeId !== null) {
    eventData.assignee_id = assigneeId
  }

  // Prepare Pusher trigger request body
  const triggerBody = {
    name: eventName,
    channel: channelName,
    data: eventData,
  }
  const bodyString = JSON.stringify(triggerBody)

  // Generate Pusher signature
  const signature = generatePusherSignature(bodyString, config.pusherAppSecret)

  // Construct Pusher trigger URL
  const url = `https://api-${config.pusherCluster}.pusher.com/apps/${config.pusherAppId}/trigger`

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Pusher-Key': config.pusherAppKey,
      'X-Pusher-Signature': signature,
    },
    body: bodyString,
  })

  if (!response.ok) {
    throw new Error(`Pusher trigger failed: ${response.status} ${response.statusText} at ${url}`)
  }

  return {
    pusherChannel: channelName,
    pusherEvent: eventName,
    ticketId,
    status,
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, ZendeskWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

// Contract test - must be at top level with exact title 'contract'
describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      zendeskWebhookSecret: 'test-secret',
      pusherAppId: '123456',
      pusherAppKey: 'test-key',
      pusherAppSecret: 'test-secret',
      pusherCluster: 'mt1',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as ZendeskWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.ticketId).toBe(987654)
    expect(result.pusherChannel).toBe('presence-ticket-987654')
    expect(result.pusherEvent).toBe('ticket.updated')
    expect(result.status).toBe('open')
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let validPayload: ZendeskWebhookPayload

  beforeEach(() => {
    baseConfig = {
      zendeskWebhookSecret: 'zendesk-secret',
      pusherAppId: '123456',
      pusherAppKey: 'pusher-key',
      pusherAppSecret: 'pusher-secret',
      pusherCluster: 'mt1',
    }
    validPayload = {
      account_id: 123456,
      id: '01HQGJ5H8F8Z7Y6X5W4V3U2T2',
      type: 'zen:event-type:ticket.updated',
      subject: 'zen:ticket:987654',
      time: '2025-01-24T16:15:00.000Z',
      zendesk_event_version: '2022-06-20',
      event: { type: 'change', source: 'api' },
      detail: {
        id: 987654,
        subject: 'Test ticket',
        priority: 'normal',
        status: 'open',
        assignee_id: 334455,
        updated_at: '2025-01-24T16:15:00Z',
        current: { status: 'open', assignee_id: 334455, priority: 'normal' },
        previous: { status: 'new', assignee_id: null, priority: 'low' },
      },
    }
  })

  it('sends correct request to Pusher trigger endpoint with proper auth', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://api-mt1.pusher.com/apps/123456/trigger')
      expect(req.headers.get('content-type')).toBe('application/json')
      expect(req.headers.get('x-pusher-key')).toBe('pusher-key')
      expect(req.headers.get('x-pusher-signature')).toBeDefined()
      const body = req.json as Record<string, unknown>
      expect(body.name).toBe('ticket.updated')
      expect(body.channel).toBe('presence-ticket-987654')
      expect(body.data).toEqual({
        status: 'open',
        assignee_id: 334455,
        updated_at: '2025-01-24T16:15:00Z',
      })
      return jsonResponse({}, 200)
    })

    await handle(validPayload, { ...baseConfig, fetch })
    expect(calls).toHaveLength(1)
  })

  it('includes assignee_id in event data when present', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200))
    await handle(validPayload, { ...baseConfig, fetch })
    const body = calls[0].json as Record<string, unknown>
    expect(body.data).toHaveProperty('assignee_id', 334455)
  })

  it('omits assignee_id when null', async () => {
    const payload = {
      ...validPayload,
      detail: { ...validPayload.detail, assignee_id: null },
    }
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200))
    await handle(payload, { ...baseConfig, fetch })
    const body = calls[0].json as Record<string, unknown>
    expect(body.data).not.toHaveProperty('assignee_id')
  })

  it('throws on missing detail.id', async () => {
    const payload = {
      ...validPayload,
      detail: { ...validPayload.detail, id: undefined as unknown },
    }
    await expect(handle(payload as unknown as ZendeskWebhookPayload, baseConfig)).rejects.toThrow(
      'Missing required field: detail.id'
    )
  })

  it('throws on missing detail.status', async () => {
    const payload = {
      ...validPayload,
      detail: { ...validPayload.detail, status: undefined as unknown },
    }
    await expect(handle(payload as unknown as ZendeskWebhookPayload, baseConfig)).rejects.toThrow(
      'Missing required field: detail.status'
    )
  })

  it('throws on missing detail.updated_at', async () => {
    const payload = {
      ...validPayload,
      detail: { ...validPayload.detail, updated_at: undefined as unknown },
    }
    await expect(handle(payload as unknown as ZendeskWebhookPayload, baseConfig)).rejects.toThrow(
      'Missing required field: detail.updated_at'
    )
  })

  it('throws on non-2xx response from Pusher', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    await expect(handle(validPayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Pusher trigger failed: 401 Unauthorized at https://api-mt1.pusher.com/apps/123456/trigger'
    )
  })

  it('uses injected fetch instead of global', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200))
    await handle(validPayload, { ...baseConfig, fetch })
    expect(calls).toHaveLength(1)
  })

  it('formats channel name with presence- prefix', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200))
    await handle(validPayload, { ...baseConfig, fetch })
    const body = calls[0].json as Record<string, unknown>
    expect(body.channel).toBe('presence-ticket-987654')
  })

  it('returns correct result structure', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const result = await handle(validPayload, { ...baseConfig, fetch })
    expect(result).toEqual({
      pusherChannel: 'presence-ticket-987654',
      pusherEvent: 'ticket.updated',
      ticketId: 987654,
      status: 'open',
    })
  })
})

