  pusherAppSecret: string
  /** Pusher cluster identifier (e.g., 'mt1', 'eu', 'ap1') */
  pusherCluster: string
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
}

export interface ZendeskWebhookPayload {
  account_id: number
  id: string
  type: string
  subject: string
  time: string
  zendesk_event_version: string
  event: {
    type: string
    source: string
  }
  detail: {
