    current: {
      status: string
      assignee_id: number | null
      priority: string
    }
    previous: {
      status: string
      assignee_id: number | null
      priority: string
    }
  }
}

export interface HandleResult {
  pusherChannel: string
  pusherEvent: string
  ticketId: number
  status: string
}

function validatePayload(payload: unknown): asserts payload is ZendeskWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Invalid payload: expected object')
  }
  const p = payload as Record<string, unknown>
  if (!p.detail || typeof p.detail !== 'object') {
    throw new Error('Missing required field: detail')
  }
  const detail = p.detail as Record<string, unknown>
  if (typeof detail.id !== 'number') {
    throw new Error('Missing required field: detail.id (ticket ID)')
  }
  if (typeof detail.status !== 'string') {
    throw new Error('Missing required field: detail.status')
  }
  if (typeof detail.updated_at !== 'string') {
    throw new Error('Missing required field: detail.updated_at')
  }
}

function verifyZendeskSignature(
  payload: string,
  signatureHeader: string | null,
  secret: string
): void {
  if (!signatureHeader) {
    throw new Error('Missing X-Zendesk-Webhook-Signature header')
  }
  const expected = createHmac('sha256', secret).update(payload).digest('hex')
  if (signatureHeader !== expected) {
    throw new Error('Invalid Zendesk webhook signature')
  }
}

function generatePusherSignature(
  body: string,
  secret: string
): string {
  return createHmac('sha256', secret).update(body).digest('hex')
}

export async function handle(
  payload: ZendeskWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  // Validate required fields
  validatePayload(payload)

  const { detail } = payload
  const ticketId = detail.id
  const status = detail.status
  const assigneeId = detail.assignee_id
  const updatedAt = detail.updated_at

  // Format channel name to match documented endpoint: ticket-{id} (no presence- prefix in URL)
  const channelName = `ticket-${ticketId}`
  const eventName = 'ticket.updated'

  // Build event data
  const eventData: Record<string, unknown> = {
    status,
    updated_at: updatedAt,
  }
  if (assigneeId !== null) {
    eventData.assignee_id = assigneeId
  }

  // Prepare Pusher event request body for /channels/{channel}/events endpoint
  const triggerBody = {
    name: eventName,
    data: eventData,
  }
  const bodyString = JSON.stringify(triggerBody)

  // Generate Pusher signature (HMAC-SHA256 of request body)
  const signature = generatePusherSignature(bodyString, config.pusherAppSecret)

  // Construct Pusher event URL per documented endpoint
  const url = `https://api-${config.pusherCluster}.pusher.com/apps/${config.pusherAppId}/channels/${channelName}/events`

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Pusher-Key': config.pusherAppKey,
      'X-Pusher-Signature': signature,
    },
    body: bodyString,
  })

  if (!response.ok) {
    throw new Error(`Pusher event trigger failed: ${response.status} ${response.statusText} at ${url}`)
  }

  return {
    pusherChannel: channelName,
    pusherEvent: eventName,
    ticketId,
    status,
  }
}

